class Particle {
	constructor(pos, clr) {
		this.pos = pos;
		this.clr = clr;
		this.alpha = 50;
		this.clr.setAlpha(this.alpha);
		// vals
		const v = 3; // random(2.2, 3.3);
		this.a = pow(random(-v, v), v);
		this.b = pow(random(-v, v), v);
		this.c = pow(random(-v, v), v);
		this.d = pow(random(-v, v), v);
	}

	update() {
		let dx = sin(this.a * this.pos.y) - cos(this.b * this.pos.x);
    let dy = sin(this.c * this.pos.x) - cos(this.d * this.pos.y);
    this.pos.x += dx + noise(dx) - 0.5;
    this.pos.y += dy + noise(dy) - 0.5;
		if (this.alpha > 0) this.alpha -= 0.25
		this.clr.setAlpha(this.alpha);
	}

	show() {
		stroke(this.clr);
		strokeWeight(2);
		point(this.pos.x, this.pos.y);
	}

}

