const NUM_PARTICLES = 250;
let particles;
let startFrame = 1, duration = 600;

function setup(pos = null) {
	if (!pos) {
		createCanvas(windowWidth, windowHeight);
		describe("particles of two-colored range oriented in a horizontal centered line meandering");
		frameRate(60);
		blendMode(BLEND);
		background(2, 2, 12);
		blendMode(ADD);
		stroke("lightblue");
	}

	particles = [];
	const pts = getRandomPts(pos);
	const c1 = color(random(["cyan", "pink", "yellow"]));
	const c2 = color(random(["blue", "darkred", "darkorange"]));
	for (let i = 0; i < NUM_PARTICLES; i++) {
		const f = random();
		const segIdx = ~~((pts.length-1) * f);
		const segFct = (f - segIdx * (1/(pts.length-1))) / (1/(pts.length-1));

		const x = ~~lerp(pts[segIdx].x, pts[segIdx+1].x, segFct);
		const y = ~~lerp(pts[segIdx].y, pts[segIdx+1].y, segFct);
		const clr = lerpColor(c1, c2, random());

		particles.push(new Particle({x, y}, clr));
	}

	startFrame = frameCount;
	loop();
}

function draw() {
	// background(2, 2, 12, 16);

	for (let p of particles) {
		p.update();
		p.show();
	}

	if (frameCount > startFrame + duration) {
		// noLoop() removed for animation
	}
}

function getRandomPts(pos) {
	var pts = [];
	const typ = ~~random(4);

	const wm = pos ? pos.x : width/2;
	const wf = random(0.1, 0.9);
	const ww = ~~(width*wf);
	const w1 = wm - ww/2;
	const w2 = wm + ww/2;

	const hm = pos ? pos.y : height/2;
	const hf = random(0.1, 0.9);
	const hh = ~~(height*hf);
	const h1 = hm - hh/2;
	const h2 = hm + hh/2;

	console.log(`ww ${ww}, w1 ${w1}, w2 ${w2}, wm ${wm}`);
	console.log(`hh ${hh}, h1 ${h1}, h2 ${h2}, hm ${hm}`);

	if (typ === 0) {
		// line
		pts.push({x: w1, y: hm});
		pts.push({x: w2, y: hm});

	} else if (typ === 1) {
		// line with points in between
		pts.push({x: w1, y: randomGaussian(hm, 100)});
		const numPts = ~~pow(random(100), 0.2);
		for (let i = 0; i < numPts; i++) {
			var f = (i+1) / (numPts+1);
			var x = lerp(w1, w2, f);
			var y = ~~random(h1, h2);
			pts.push({x, y});
		}
		pts.push({x: w2, y: randomGaussian(hm, 100)});

	} else if (typ === 2) {
		// bezier
		const p1 = {x: w1, y: ~~random(h1, h2)};
		const p2 = {x: w2, y: ~~random(h1, h2)};
		const a1 = {x: ~~random(w1, w2), y: ~~random(h1, h2)}
		const a2 = {x: ~~random(w1, w2), y: ~~random(h1, h2)}
		pts.push({x: p1.x, y: p1.y});
		var numPts = 100;
		for (let i = 0; i < numPts; i++) {
			var f = random();
			var x = ~~bezierPoint(p1.x, a1.x, a2.x, p2.x, f);
			var y = ~~bezierPoint(p1.y, a1.y, a2.y, p2.y, f);
			pts.push({x, y});
		}
		pts.push({x: p2.x, y: p2.y});

	}
		else {
		// circle
		const radius = min(w2-w1, h2-h1) * 0.4;
		var numPts = ~~sqrt(random(100)) + 3;
		for (let i = 0; i <= numPts; i++) {
			const a = i/numPts * TWO_PI - HALF_PI;
			var x = cos(a) * radius + wm;
			var y = sin(a) * radius + hm;
			pts.push({x, y});
		}
	}

	return pts;
}

